import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong association to outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        y1 = feats.x[feats.y==1, i]
        y0 = feats.x[feats.y==0, i]
        if len(y1) > 0 and len(y0) > 0:
            tstat, pval = stats.ttest_ind(y1, y0, equal_var=False)
            mean_diff = np.mean(y1) - np.mean(y0)
            auc = 0.5 + 0.5 * (np.mean(y1 > y0) - np.mean(y0 > y1))
            effects.append((fid, abs(mean_diff), abs(tstat), pval, auc))

    effects.sort(key=lambda x: x[2], reverse=True)

    # Select top features
    top_features = [f[0] for f in effects[:20]]

    # Check for correlated pairs (|r| >= 0.6)
    pairs = []
    for i in range(len(top_features)):
        for j in range(i+1, len(top_features)):
            fid1, fid2 = top_features[i], top_features[j]
            col1, col2 = feats.column(fid1), feats.column(fid2)
            if col1 < feats.x.shape[1] and col2 < feats.x.shape[1]:
                try:
                    corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0,1]
                    if abs(corr) >= 0.6:
                        pairs.append((fid1, fid2))
                except:
                    continue

    # Try product terms
    best_score = -np.inf
    best_product = None

    for fid1, fid2 in pairs:
        col1, col2 = feats.column(fid1), feats.column(fid2)
        if col1 >= feats.x.shape[1] or col2 >= feats.x.shape[1]:
            continue
        prod = feats.x[:, col1] * feats.x[:, col2]

        # Get all features except the two in the pair
        other_features = [fid for fid in top_features if fid != fid1 and fid != fid2]

        # Build feature matrix
        X_cols = []
        valid_features = []
        for fid in other_features:
            col_idx = feats.column(fid)
            if col_idx < feats.x.shape[1]:
                X_cols.append(feats.x[:, col_idx])
                valid_features.append(fid)

        # Add product term
        X_cols.append(prod)

        if len(X_cols) > 0:
            try:
                X = np.column_stack(X_cols)

                # Handle case where X might be empty or have issues
                if X.ndim == 1:
                    X = X.reshape(-1, 1)

                model = LogisticRegression(penalty='l2', C=1.0, max_iter=1000, random_state=42)
                model.fit(X, feats.y)
                score = model.score(X, feats.y)
                if score > best_score:
                    best_score = score
                    best_product = (fid1, fid2)
            except:
                continue

    # If we found a good product term, return it
    if best_product:
        return Design(
            drivers=(best_product[0], best_product[1]),
            columns=(best_product[0], best_product[1]),
            products=(best_product,),
            loadings={best_product[0]: 1.0, best_product[1]: 1.0}
        )

    # Otherwise, return top individual features
    drivers = tuple(f[0] for f in effects[:MAX_DRIVERS] if f[2] > 2.0)

    if not drivers:
        return Design(
            drivers=(),
            columns=(),
            products=(),
            loadings={}
        )

    # Return top features
    return Design(
        drivers=drivers,
        columns=drivers,
        products=(),
        loadings={fid: 1.0 for fid in drivers}
    )
